string md5_to_string(const unsigned char *digest) {
  char buf[MD5_DIGEST_LENGTH * 2 + 1];
  for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
    sprintf(&buf[2 * i], "%02x", digest[i]);
  }
  return string(buf);
